fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Open the application switcher dropdown next to the logo and select the Lists application, then open the 'Operations' section in its left nav. In the left 'Selected Operands' panel, use the 'Search lists to add...' box to add a list operand (type a letter, then click a result). Add a second list of the SAME entity type if the picker offers one. Once two operands are present, a 'Quick Operations' group appears — click 'Union All' (or 'Intersection'). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Success is that the operand(s) register on the canvas and, when two are present, the Venn diagram renders and the Results panel shows a record count for the operation — you do NOT need to save anything.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Adding a list from the 'Search lists to add...' picker places it as an operand chip in the Selected Operands panel (or, if the user has no lists, the 'Add Lists or Views to Compare' empty state is shown)",
    "With two same-entity operands, the Venn diagram area renders overlapping circles AND clicking a Quick Operation (Union/Intersection) produces a result count (e.g. 'N records') in the Results panel",
    "No error messages, blank screens, or crash pages"
  ]
}
